{
  "name": "DocuFill AI - License to Word",
  "description": "Automate Word document filling using AI-powered OCR from driver's license images with automatic translation and image optimization.",
  "requestFramePermissions": [
    "camera"
  ]
}

export interface ExtractedData {
  fullName: string;
  licenseNumber: string;
  dateOfBirth: string;
  issueDate: string;
  expiryDate: string;
  address: string;
  nationality: string;
  gender: string;
  class: string;
  [key: string]: string;
}

export enum ProcessStatus {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  REVIEW = 'REVIEW',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface AppState {
  templateFile: File | null;
  frontImage: File | null;
  backImage: File | null;
  status: ProcessStatus;
  extractedData: ExtractedData | null;
  error: string | null;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ExtractedData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = error => reject(error);
  });
};

export const extractDataFromLicense = async (
  front: File,
  back: File
): Promise<ExtractedData> => {
  const frontBase64 = await fileToBase64(front);
  const backBase64 = await fileToBase64(back);

  const prompt = `
    Analyze these two images of a driver's license (Front and Back).
    1. Perform OCR to extract all relevant information.
    2. Translate all field names and values to English accurately.
    3. Return the data in a valid JSON format.

    Expected Fields (Translate to English):
    - fullName
    - licenseNumber
    - dateOfBirth
    - issueDate
    - expiryDate
    - address
    - nationality
    - gender
    - class (License category)

    If a field is missing, use "N/A".
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: frontBase64, mimeType: front.type } },
        { inlineData: { data: backBase64, mimeType: back.type } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          fullName: { type: Type.STRING },
          licenseNumber: { type: Type.STRING },
          dateOfBirth: { type: Type.STRING },
          issueDate: { type: Type.STRING },
          expiryDate: { type: Type.STRING },
          address: { type: Type.STRING },
          nationality: { type: Type.STRING },
          gender: { type: Type.STRING },
          class: { type: Type.STRING },
        },
        required: ["fullName", "licenseNumber"]
      }
    }
  });

  const jsonStr = response.text.trim();
  return JSON.parse(jsonStr) as ExtractedData;
};

import PizZip from "pizzip";
import Docxtemplater from "docxtemplater";
import { ExtractedData } from "../types";

// In a real environment, you'd use the official ImageModule. 
// For this demo, we handle text replacement. 
// Note: docxtemplater image module is often a paid/separate plugin.
// We will focus on the required data mapping and text placeholders.

export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  frontImg: File,
  backImg: File
): Promise<Blob> => {
  const arrayBuffer = await template.arrayBuffer();
  const zip = new PizZip(arrayBuffer);

  const doc = new Docxtemplater(zip, {
    paragraphLoop: true,
    linebreaks: true,
  });

  // Prepare data for docxtemplater
  // Users should use tags like {{fullName}}, {{licenseNumber}}, etc. in their .docx
  doc.setData({
    ...data,
    // Add specific markers for user to see
    generated_at: new Date().toLocaleDateString(),
  });

  try {
    doc.render();
  } catch (error) {
    console.error("Docxtemplater Error:", error);
    throw error;
  }

  const out = doc.getZip().generate({
    type: "blob",
    mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  });

  return out;
};

export const optimizeImage = async (file: File): Promise<string> => {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');

        // Simple optimization: fix aspect ratio or scale if needed
        const scale = 0.8; 
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;

        ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);

        // Return base64 for preview
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

import React from 'react';
import { FileUp, Image as ImageIcon, CheckCircle, X } from 'lucide-react';

interface FileUploaderProps {
  label: string;
  accept: string;
  onFileSelect: (file: File | null) => void;
  selectedFile: File | null;
  icon?: 'file' | 'image';
}

const FileUploader: React.FC<FileUploaderProps> = ({ 
  label, 
  accept, 
  onFileSelect, 
  selectedFile,
  icon = 'file'
}) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      onFileSelect(e.target.files[0]);
    }
  };

  const clearFile = (e: React.MouseEvent) => {
    e.stopPropagation();
    onFileSelect(null);
  };

  return (
    <div className="flex flex-col gap-2">
      <span className="text-sm font-medium text-slate-700">{label}</span>
      <div 
        className={`relative border-2 border-dashed rounded-xl p-6 transition-all cursor-pointer group
          ${selectedFile 
            ? 'border-emerald-200 bg-emerald-50' 
            : 'border-slate-200 bg-white hover:border-indigo-400 hover:bg-indigo-50/30'}`}
        onClick={() => document.getElementById(`input-${label}`)?.click()}
      >
        <input 
          id={`input-${label}`}
          type="file" 
          accept={accept} 
          className="hidden" 
          onChange={handleChange}
        />

        <div className="flex flex-col items-center justify-center gap-3 text-center">
          {selectedFile ? (
            <>
              <CheckCircle className="w-10 h-10 text-emerald-500" />
              <div className="flex flex-col items-center">
                <p className="text-sm font-semibold text-emerald-700 truncate max-w-[200px]">
                  {selectedFile.name}
                </p>
                <button 
                  onClick={clearFile}
                  className="mt-2 text-xs text-red-500 hover:text-red-700 flex items-center gap-1"
                >
                  <X size={12} /> Remove
                </button>
              </div>
            </>
          ) : (
            <>
              <div className="p-3 bg-indigo-100 text-indigo-600 rounded-full group-hover:bg-indigo-200 transition-colors">
                {icon === 'file' ? <FileUp size={24} /> : <ImageIcon size={24} />}
              </div>
              <div>
                <p className="text-sm font-medium text-slate-600">
                  Click to upload or drag and drop
                </p>
                <p className="text-xs text-slate-400 mt-1">
                  {accept.includes('image') ? 'JPG, PNG up to 10MB' : 'Word Document (.docx)'}
                </p>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default FileUploader;

