export default DataPreview;

import React, { useState, useCallback } from 'react';
import { FileText, Cpu, CheckCircle, AlertCircle, Download, RefreshCcw, Loader2 } from 'lucide-react';
import FileUploader from './components/FileUploader';
import DataPreview from './components/DataPreview';
import { extractDataFromLicense } from './services/geminiService';
import { generateFilledDoc, optimizeImage } from './services/docService';
import { AppState, ProcessStatus, ExtractedData } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    templateFile: null,
    frontImage: null,
    backImage: null,
    status: ProcessStatus.IDLE,
    extractedData: null,
    error: null,
  });

  const [previews, setPreviews] = useState<{ front: string | null; back: string | null }>({
    front: null,
    back: null,
  });

  const handleProcess = async () => {
    if (!state.templateFile || !state.frontImage || !state.backImage) {
      setState(prev => ({ ...prev, error: "Please upload all required files." }));
      return;
    }

    setState(prev => ({ ...prev, status: ProcessStatus.PROCESSING, error: null }));

    try {
      // 1. Optimize images for preview/processing
      const frontOpt = await optimizeImage(state.frontImage);
      const backOpt = await optimizeImage(state.backImage);
      setPreviews({ front: frontOpt, back: backOpt });

      // 2. OCR and Translation via Gemini
      const data = await extractDataFromLicense(state.frontImage, state.backImage);

      setState(prev => ({
        ...prev,
        status: ProcessStatus.REVIEW,
        extractedData: data
      }));
    } catch (err: any) {
      console.error(err);
      setState(prev => ({
        ...prev,
        status: ProcessStatus.ERROR,
        error: "Failed to process images. Ensure they are clear and contain valid license data."
      }));
    }
  };

  const handleFinalize = async () => {
    if (!state.templateFile || !state.extractedData || !state.frontImage || !state.backImage) return;

    try {
      const blob = await generateFilledDoc(
        state.templateFile,
        state.extractedData,
        state.frontImage,
        state.backImage
      );

      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Filled_Template_${new Date().getTime()}.docx`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      setState(prev => ({ ...prev, status: ProcessStatus.COMPLETED }));
    } catch (err) {
      setState(prev => ({ ...prev, error: "Error generating Word document." }));
    }
  };

  const reset = () => {
    setState({
      templateFile: null,
      frontImage: null,
      backImage: null,
      status: ProcessStatus.IDLE,
      extractedData: null,
      error: null,
    });
    setPreviews({ front: null, back: null });
  };

  return (
    <div className="min-h-screen flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8">
      {/* Header */}
      <div className="max-w-4xl w-full text-center mb-12">
        <div className="inline-flex items-center justify-center p-3 bg-indigo-600 text-white rounded-2xl shadow-lg mb-6">
          <FileText size={32} />
        </div>
        <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight">
          DocuFill <span className="text-indigo-600">AI</span>
        </h1>
        <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">
          Automate document entry. Upload your driver's license and a Word template to instantly generate professional translated documents.
        </p>
      </div>

      <main className="max-w-4xl w-full">
        {state.status === ProcessStatus.IDLE && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            {/* Template Section */}
            <div className="col-span-full md:col-span-1">
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-full">
                <div className="flex items-center gap-3 mb-4">
                  <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg">
                    <FileText size={20} />
                  </div>
                  <h2 className="text-lg font-semibold text-slate-800">1. Upload Template</h2>
                </div>
                <FileUploader 
                  label="Word Template (.docx)" 
                  accept=".docx" 
                  selectedFile={state.templateFile}
                  onFileSelect={(file) => setState(prev => ({ ...prev, templateFile: file }))}
                />
                <p className="mt-4 text-xs text-slate-400">
                  Ensure your document contains placeholders like <code className="bg-slate-100 px-1 rounded text-indigo-600">{"{{fullName}}"}</code> and <code className="bg-slate-100 px-1 rounded text-indigo-600">{"{{licenseNumber}}"}</code>.
                </p>
              </div>
            </div>

            {/* Images Section */}
            <div className="col-span-full md:col-span-1 space-y-4">
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-full">
                <div className="flex items-center gap-3 mb-4">
                  <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg">
                    <Cpu size={20} />
                  </div>
                  <h2 className="text-lg font-semibold text-slate-800">2. Upload License</h2>
                </div>
                <div className="grid grid-cols-1 gap-4">
                  <FileUploader 
                    label="Front Image" 
                    accept="image/*" 
                    icon="image"
                    selectedFile={state.frontImage}
                    onFileSelect={(file) => setState(prev => ({ ...prev, frontImage: file }))}
                  />
                  <FileUploader 
                    label="Back Image" 
                    accept="image/*" 
                    icon="image"
                    selectedFile={state.backImage}
                    onFileSelect={(file) => setState(prev => ({ ...prev, backImage: file }))}
                  />
                </div>
              </div>
            </div>

            {/* Error Message */}
            {state.error && (
              <div className="col-span-full bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-xl flex items-center gap-3">
                <AlertCircle size={20} />
                <span className="text-sm font-medium">{state.error}</span>
              </div>
            )}

            {/* Process Button */}
            <div className="col-span-full flex justify-center mt-4">
              <button 
                onClick={handleProcess}
                disabled={!state.templateFile || !state.frontImage || !state.backImage}
                className="group relative inline-flex items-center justify-center px-10 py-4 font-bold text-white transition-all duration-200 bg-indigo-600 font-pj rounded-xl focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-indigo-200"
              >
                <Cpu className="w-5 h-5 mr-2 group-hover:rotate-12 transition-transform" />
                Start AI Processing
              </button>
            </div>
          </div>
        )}

        {state.status === ProcessStatus.PROCESSING && (
          <div className="bg-white p-12 rounded-3xl border border-slate-200 shadow-xl text-center space-y-6 animate-in zoom-in-95 duration-500">
            <div className="relative inline-flex">
              <div className="w-16 h-16 bg-indigo-100 rounded-full flex items-center justify-center">
                <Loader2 className="w-8 h-8 text-indigo-600 animate-spin" />
              </div>
            </div>
            <div>
              <h2 className="text-2xl font-bold text-slate-900">AI is Analyzing Your Data</h2>
              <p className="text-slate-500 mt-2 max-w-sm mx-auto">
                Our vision model is extracting details, translating fields, and optimizing your images for the document.
              </p>
            </div>
            <div className="w-full bg-slate-100 rounded-full h-2 max-w-xs mx-auto overflow-hidden">
              <div className="bg-indigo-600 h-full animate-[progress_2s_ease-in-out_infinite]" style={{ width: '40%' }}></div>
            </div>
          </div>
        )}

        {state.status === ProcessStatus.REVIEW && state.extractedData && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              {/* Images Preview Sidebar */}
              <div className="lg:col-span-1 space-y-4">
                <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest px-1">Source Images</h3>
                {previews.front && (
                  <div className="rounded-xl overflow-hidden border border-slate-200 shadow-sm aspect-[1.58/1] relative group">
                    <img src={previews.front} alt="Front" className="w-full h-full object-cover" />
                    <div className="absolute top-2 left-2 px-2 py-1 bg-black/50 backdrop-blur-sm text-[10px] text-white rounded font-bold uppercase">Front Optimized</div>
                  </div>
                )}
                {previews.back && (
                  <div className="rounded-xl overflow-hidden border border-slate-200 shadow-sm aspect-[1.58/1] relative">
                    <img src={previews.back} alt="Back" className="w-full h-full object-cover" />
                    <div className="absolute top-2 left-2 px-2 py-1 bg-black/50 backdrop-blur-sm text-[10px] text-white rounded font-bold uppercase">Back Optimized</div>
                  </div>
                )}
              </div>

              {/* Data Table */}
              <div className="lg:col-span-2">
                <DataPreview 
                  data={state.extractedData} 
                  onChange={(newData) => setState(prev => ({ ...prev, extractedData: newData }))} 
                />

                <div className="mt-8 flex flex-col sm:flex-row items-center justify-between gap-4">
                  <button 
                    onClick={reset}
                    className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors px-4 py-2"
                  >
                    <RefreshCcw size={18} />
                    Start Over
                  </button>
                  <button 
                    onClick={handleFinalize}
                    className="flex items-center gap-2 px-8 py-4 bg-emerald-600 text-white font-bold rounded-xl hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-100"
                  >
                    <Download size={20} />
                    Generate & Download Word
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {state.status === ProcessStatus.COMPLETED && (
          <div className="bg-white p-12 rounded-3xl border border-slate-200 shadow-xl text-center space-y-6 animate-in zoom-in-95 duration-500">
            <div className="w-16 h-16 bg-emerald-100 rounded-full flex items-center justify-center mx-auto">
              <CheckCircle className="w-10 h-10 text-emerald-600" />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-slate-900">Successfully Generated!</h2>
              <p className="text-slate-500 mt-2">
                Your file has been downloaded. You can now start a new task.
              </p>
            </div>
            <button 
              onClick={reset}
              className="inline-flex items-center gap-2 px-6 py-3 border border-slate-200 rounded-xl font-medium text-slate-600 hover:bg-slate-50 transition-colors"
            >
              <RefreshCcw size={18} />
              Process Another License
            </button>
          </div>
        )}
      </main>

      <footer className="mt-20 text-slate-400 text-sm">
        Powered by Gemini 3 Flash & docxtemplater
      </footer>

      <style>{`
        @keyframes progress {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(250%); }
        }
      `}</style>
    </div>
  );
};

export default App;

