import PizZip from "pizzip";
import Docxtemplater from "docxtemplater";
// @ts-ignore
import ImageModule from "docxtemplater-image-module-free";
import { ExtractedData } from "../types";

/**
 * Converts a File to a DataURL string.
 */
export const fileToDataURL = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * Optimizes image for document insertion and returns a Base64 string.
 */
export const optimizeImage = async (file: File): Promise<string> => {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');

        // Target a reasonable size for Word documents
        const maxWidth = 800;
        const scale = img.width > maxWidth ? maxWidth / img.width : 1;
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;

        ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.8));
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

/**
 * Generates a filled Word document with text and images.
 */
export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  frontImg: string, // Base64
  backImg: string   // Base64
): Promise<Blob> => {
  const arrayBuffer = await template.arrayBuffer();
  const zip = new PizZip(arrayBuffer);

  // Configure Image Module
  const opts = {
    centered: false,
    getImage: (tagValue: string) => {
      // tagValue will be the base64 string provided in data
      const base64 = tagValue.split(',')[1] || tagValue;
      const binaryString = window.atob(base64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return bytes.buffer;
    },
    getSize: () => [300, 200], // Default size for the images in the Word doc
  };
  const imageModule = new ImageModule(opts);

  const doc = new Docxtemplater(zip, {
    paragraphLoop: true,
    linebreaks: true,
    modules: [imageModule],
  });

  // Comprehensive data mapping for template compatibility
  // Supports camelCase, snake_case, and uppercase
  const templateData = {
    ...data,
    // Aliases
    full_name: data.fullName,
    license_number: data.licenseNumber,
    id_number: data.licenseNumber,
    dob: data.dateOfBirth,
    date_of_birth: data.dateOfBirth,
    issue_date: data.issueDate,
    expiry_date: data.expiryDate,
    class_type: data.class,
    // Images (tags: {%front_image}, {%back_image})
    front_image: frontImg,
    back_image: backImg,
    license_front: frontImg,
    license_back: backImg,
    generated_at: new Date().toLocaleDateString(),
  };

  try {
    doc.render(templateData);
  } catch (error: any) {
    console.error("Docxtemplater Rendering Error:", error);
    if (error.properties && error.properties.errors) {
      error.properties.errors.forEach((err: any) => console.error(err));
    }
    throw error;
  }

  const out = doc.getZip().generate({
    type: "blob",
    mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  });

  return out;
};

