import PizZip from "pizzip";
import Docxtemplater from "docxtemplater";
// @ts-ignore
import ImageModule from "docxtemplater-image-module-free";
import { ExtractedData } from "../types";

/**
 * Optimiza la imagen para su inserción en Word.
 */
export const optimizeImage = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');

        // Tamaño máximo para evitar que el documento sea excesivamente pesado
        const maxWidth = 1000;
        const scale = img.width > maxWidth ? maxWidth / img.width : 1;
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;

        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        }

        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
      img.onerror = reject;
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * Genera el documento Word rellenando los placeholders.
 */
export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  frontImgData: string,
  backImgData: string
): Promise<Blob> => {
  try {
    const arrayBuffer = await template.arrayBuffer();
    const zip = new PizZip(arrayBuffer);

    // Configuración del módulo de imágenes
    // El módulo espera que retornemos el contenido de la imagen como ArrayBuffer
    const imageOptions = {
      centered: false,
      getImage: (tagValue: string) => {
        const base64 = tagValue.includes(',') ? tagValue.split(',')[1] : tagValue;
        const binaryString = window.atob(base64);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }
        return bytes.buffer;
      },
      getSize: () => [280, 180], // Tamaño en píxeles dentro del Word
    };

    // Es posible que en ESM el módulo esté bajo .default
    const ResolvedImageModule = ImageModule.default || ImageModule;
    const imageModule = new ResolvedImageModule(imageOptions);

    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      modules: [imageModule],
    });

    // Mapeo exhaustivo para cubrir cualquier estilo de etiqueta en el Machote
    const viewData = {
      ...data,
      // Versiones en minúsculas y snake_case para compatibilidad
      full_name: data.fullName,
      license_number: data.licenseNumber,
      license_id: data.licenseNumber,
      expiry_date: data.expiryDate,
      birth_date: data.dateOfBirth,
      dob: data.dateOfBirth,
      address_line: data.address,
      issue_date: data.issueDate,
      nationality_val: data.nationality,
      // Etiquetas de Imagen (usar {%tag} en el Word)
      license_front: frontImgData,
      license_back: backImgData,
      front_image: frontImgData,
      back_image: backImgData,
      // Metadata adicional
      processing_date: new Date().toLocaleDateString(),
    };

    doc.render(viewData);

    const out = doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });

    return out;
  } catch (error: any) {
    console.error("Error detallado en la generación del DOCX:", error);
    // Errores específicos de docxtemplater
    if (error.properties && error.properties.errors) {
      const messages = error.properties.errors.map((e: any) => e.message).join(", ");
      throw new Error(`Error de plantillas: ${messages}`);
    }
    throw error;
  }
};

