import PizZip from "pizzip";
import Docxtemplater from "docxtemplater";
// @ts-ignore
import ImageModule from "docxtemplater-image-module-free";
import { ExtractedData } from "../types";

/**
 * Optimiza y prepara la imagen.
 */
export const optimizeImage = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const maxWidth = 800;
        const scale = img.width > maxWidth ? maxWidth / img.width : 1;
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        }
        resolve(canvas.toDataURL('image/jpeg', 0.8));
      };
      img.onerror = reject;
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * Función principal de generación de Word.
 */
export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  frontImgBase64: string,
  backImgBase64: string
): Promise<Blob> => {
  try {
    const arrayBuffer = await template.arrayBuffer();
    const zip = new PizZip(arrayBuffer);

    // Configuración robusta del módulo de imágenes
    const imageOptions = {
      centered: false,
      getImage: (tagValue: string) => {
        const base64 = tagValue.split(',')[1] || tagValue;
        const binaryString = window.atob(base64);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }
        return bytes.buffer;
      },
      getSize: () => [250, 160], // Tamaño sugerido en el documento
    };

    const ResolvedImageModule = ImageModule.default || ImageModule;
    const imageModule = new ResolvedImageModule(imageOptions);

    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      modules: [imageModule],
      // Importante: Si una etiqueta no existe, no lances error, pon un espacio vacío
      nullGetter: (part: any) => {
        if (!part.module && part.type === "placeholder") {
          return "";
        }
        return "";
      }
    });

    // Mapeo duplicado (CamelCase y snake_case) para máxima compatibilidad
    const fullData = {
      // Tags de texto estándar
      fullName: data.fullName,
      full_name: data.fullName,
      licenseNumber: data.licenseNumber,
      license_number: data.licenseNumber,
      dateOfBirth: data.dateOfBirth,
      date_of_birth: data.dateOfBirth,
      dob: data.dateOfBirth,
      address: data.address,
      expiryDate: data.expiryDate,
      expiry_date: data.expiryDate,
      issueDate: data.issueDate,
      issue_date: data.issueDate,
      nationality: data.nationality,
      gender: data.gender,
      class: data.class,

      // Tags de imagen (Se usan con {%tag} en el Word)
      license_front: frontImgBase64,
      front_image: frontImgBase64,
      license_back: backImgBase64,
      back_image: backImgBase64,

      // Info extra
      today: new Date().toLocaleDateString()
    };

    doc.render(fullData);

    const out = doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });

    return out;
  } catch (error: any) {
    console.error("Error crítico docxtemplater:", error);
    throw error;
  }
};

