 */
export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  frontImgBase64: string,
  backImgBase64: string
): Promise<Blob> => {
  try {
    const arrayBuffer = await template.arrayBuffer();
    const zip = new PizZip(arrayBuffer);

    const imageOptions = {
      centered: false,
      getImage: (tagValue: string) => {
        const base64 = tagValue.split(',')[1] || tagValue;
        const binaryString = window.atob(base64);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }
        return bytes.buffer;
      },
      getSize: () => [280, 180], // Tamaño predeterminado en el documento
    };

    const ResolvedImageModule = ImageModule.default || ImageModule;
    const imageModule = new ResolvedImageModule(imageOptions);

    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      modules: [imageModule],
      nullGetter: () => "" // Evita que aparezca "undefined" en el Word
    });

    // Mapeo exhaustivo para que el usuario pueda usar nombres en español o inglés
    const fullData = {
      // Texto
      fullName: data.fullName,
      nombreCompleto: data.fullName,
      licenseNumber: data.licenseNumber,
      numeroLicencia: data.licenseNumber,
      dateOfBirth: data.dateOfBirth,
      fechaNacimiento: data.dateOfBirth,
      address: data.address,
      direccion: data.address,
      expiryDate: data.expiryDate,
      fechaVencimiento: data.expiryDate,
      issueDate: data.issueDate,
      fechaExpedicion: data.issueDate,
      nationality: data.nationality,
      nacionalidad: data.nationality,
      gender: data.gender,
      genero: data.gender,
      class: data.class,
      clase: data.class,

      // Imágenes (Usar {%etiqueta} en el Word)
      license_front: frontImgBase64,
      foto_frente: frontImgBase64,
      license_back: backImgBase64,
      foto_reverso: backImgBase64,

      today: new Date().toLocaleDateString()
    };

    doc.render(fullData);

    const out = doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });

    return out;
  } catch (error: any) {
