import PizZip from "pizzip";
import Docxtemplater from "docxtemplater";
// @ts-ignore
import ImageModule from "docxtemplater-image-module-free";
import { ExtractedData } from "../types";

/**
 * Prepara la imagen para que Word la acepte sin errores.
 */
export const optimizeImage = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        // Tamaño moderado para no saturar el Word
        const maxWidth = 1000;
        const scale = img.width > maxWidth ? maxWidth / img.width : 1;
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        }
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
      img.onerror = () => reject(new Error("Error al procesar la imagen."));
      img.src = e.target?.result as string;
    };
    reader.onerror = () => reject(new Error("Error al leer el archivo."));
    reader.readAsDataURL(file);
  });
};

/**
 * Genera el documento Word inyectando los datos.
 */
export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  frontImgBase64: string,
  backImgBase64: string
): Promise<Blob> => {
  try {
    const content = await template.arrayBuffer();
    const zip = new PizZip(content);

    // Configuración del módulo de imágenes
    const imageOptions = {
      centered: false,
      getImage: (tagValue: string) => {
        try {
          const base64 = tagValue.split(',')[1] || tagValue;
          const binaryString = window.atob(base64);
          const len = binaryString.length;
          const bytes = new Uint8Array(len);
          for (let i = 0; i < len; i++) {
            bytes[i] = binaryString.charCodeAt(i);
          }
          return bytes.buffer;
        } catch (e) {
          console.error("Error al decodificar imagen para Word:", e);
          return new ArrayBuffer(0);
        }
      },
      getSize: () => [240, 150], // Tamaño fijo en pixeles
    };

    // Manejo de la importación del módulo de imagen (compatibilidad ESM)
    const ImageModuleClass = typeof ImageModule === 'function' ? ImageModule : ImageModule.default;
    const imageModule = new ImageModuleClass(imageOptions);

    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      modules: [imageModule],
    });

    // Mapeo exhaustivo (Inglés y Español)
    const fullData = {
      fullName: data.fullName || "N/A",
      nombreCompleto: data.fullName || "N/A",
      licenseNumber: data.licenseNumber || "N/A",
      numeroLicencia: data.licenseNumber || "N/A",
      dateOfBirth: data.dateOfBirth || "N/A",
      fechaNacimiento: data.dateOfBirth || "N/A",
      address: data.address || "N/A",
      direccion: data.address || "N/A",
      expiryDate: data.expiryDate || "N/A",
      fechaVencimiento: data.expiryDate || "N/A",
      issueDate: data.issueDate || "N/A",
      fechaExpedicion: data.issueDate || "N/A",
      nationality: data.nationality || "N/A",
      nacionalidad: data.nationality || "N/A",
      gender: data.gender || "N/A",
      genero: data.gender || "N/A",
      class: data.class || "N/A",
      clase: data.class || "N/A",

      // Imágenes (Usar {%etiqueta} en el Word)
      license_front: frontImgBase64,
      foto_frente: frontImgBase64,
      license_back: backImgBase64,
      foto_reverso: backImgBase64,

      today: new Date().toLocaleDateString()
    };

    // Renderizado del documento
    doc.render(fullData);

    // Generación del archivo final
    const out = doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });

    return out;
  } catch (error: any) {
    console.error("Error detallado en Docxtemplater:", error);
    // Si hay un error de "multi_error", extraer los mensajes
    const message = error.properties?.errors?.map((e: any) => e.message).join(", ") || error.message;
    throw new Error(message || "Error al procesar el archivo Word.");
  }
};

