  });

  const [previews, setPreviews] = useState<{ front: string | null; back: string | null }>({
    front: null,
    back: null,
  });

  const handleProcess = async () => {
    if (!state.templateFile || !state.frontImage || !state.backImage) {
      setState(prev => ({ ...prev, error: "Por favor, sube todos los archivos necesarios." }));
      return;
    }

    setState(prev => ({ ...prev, status: ProcessStatus.PROCESSING, error: null }));

    try {
      // Optimizar imágenes antes de enviarlas a la IA
      const frontOpt = await optimizeImage(state.frontImage);
      const backOpt = await optimizeImage(state.backImage);
      setPreviews({ front: frontOpt, back: backOpt });

      // Extraer datos con Gemini
      const data = await extractDataFromLicense(state.frontImage, state.backImage);

      setState(prev => ({
        ...prev,
        status: ProcessStatus.REVIEW,
        extractedData: data
      }));
    } catch (err: any) {
      console.error("Error en procesamiento IA:", err);
      setState(prev => ({
        ...prev,
        status: ProcessStatus.ERROR,
        error: "La IA no pudo procesar las imágenes. Asegúrate de que sean fotos claras de una licencia."
      }));
    }
  };

  const handleFinalize = async () => {
    if (!state.templateFile || !state.extractedData || !previews.front || !previews.back) {
      setState(prev => ({ ...prev, error: "Faltan datos para generar el documento." }));
      return;
