import { GoogleGenAI, Type } from "@google/genai";
import { ExtractedData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = error => reject(error);
  });
};

export const extractDataFromLicense = async (
  front: File,
  back: File
): Promise<ExtractedData> => {
  const frontBase64 = await fileToBase64(front);
  const backBase64 = await fileToBase64(back);

  const prompt = `
    Analyze these two images of a driver's license (Front and Back).

    IMPORTANT: Use the standard numerical codes often found on licenses as anchors:
    1: Surname/Last Name
    2: First Name(s)
    3: Date of Birth
    4a: Issue Date
    4b: Expiry Date
    4d: License/ID Number
    8: Address
    9: Category/Class

    Instructions:
    1. Identify fields using these numbers first.
    2. Translate all extracted values to English.
    3. If a field is missing, use "N/A".
    4. Return valid JSON.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: frontBase64, mimeType: front.type } },
        { inlineData: { data: backBase64, mimeType: back.type } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          fullName: { type: Type.STRING, description: "Combination of fields 1 and 2" },
          licenseNumber: { type: Type.STRING, description: "Field 4d or 5" },
          dateOfBirth: { type: Type.STRING, description: "Field 3" },
          issueDate: { type: Type.STRING, description: "Field 4a" },
          expiryDate: { type: Type.STRING, description: "Field 4b" },
          address: { type: Type.STRING, description: "Field 8" },
          nationality: { type: Type.STRING },
          gender: { type: Type.STRING },
          class: { type: Type.STRING, description: "Field 9" },
        },
        required: ["fullName", "licenseNumber"]
      }
    }
  });

  const jsonStr = response.text.trim();
  return JSON.parse(jsonStr) as ExtractedData;
};

