const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    templateFile: null,
    frontImage: null,
    backImage: null,
    status: ProcessStatus.IDLE,
    extractedData: null,
    error: null,
  });

  const [previews, setPreviews] = useState<{ front: string | null; back: string | null }>({
    front: null,
    back: null,
  });

  const handleProcess = async () => {
    if (!state.templateFile || !state.frontImage || !state.backImage) {
      setState(prev => ({ ...prev, error: "Sube todos los archivos primero." }));
      return;
    }
    setState(prev => ({ ...prev, status: ProcessStatus.PROCESSING, error: null }));
    try {
      const frontOpt = await optimizeImage(state.frontImage);
      const backOpt = await optimizeImage(state.backImage);
      setPreviews({ front: frontOpt, back: backOpt });
      const data = await extractDataFromLicense(state.frontImage, state.backImage);
      setState(prev => ({ ...prev, status: ProcessStatus.REVIEW, extractedData: data }));
    } catch (err: any) {
      setState(prev => ({ ...prev, status: ProcessStatus.ERROR, error: "Error analizando las imágenes." }));
    }
  };

  const handleFinalize = async () => {
    if (!state.templateFile || !state.extractedData || !previews.front || !previews.back) return;
    setState(prev => ({ ...prev, error: null }));
    try {
      const blob = await generateFilledDoc(state.templateFile, state.extractedData, previews.front, previews.back);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Llenado_${state.extractedData.fullName.replace(/\s+/g, '_')}.docx`;
      document.body.appendChild(a);
      a.click();
      setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 100);
      setState(prev => ({ ...prev, status: ProcessStatus.COMPLETED }));
    } catch (err: any) {
      setState(prev => ({ ...prev, error: err.message }));
    }
  };

