    <div className="min-h-screen bg-[#f8fafc] py-12 px-4 flex flex-col items-center">
      <header className="max-w-5xl w-full text-center mb-12">
        <div className="bg-indigo-600 w-16 h-16 rounded-2xl shadow-xl flex items-center justify-center mx-auto mb-4">
          <FileText className="text-white" size={32} />
        </div>
        <h1 className="text-3xl font-black text-slate-900">DocuFill AI</h1>
      </header>

      <main className="max-w-5xl w-full">
        {state.status === ProcessStatus.IDLE && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <aside className="lg:col-span-4 space-y-6">
              <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                  <Info size={18} className="text-indigo-600" /> Etiquetas Inteligentes
