                </p>

                <div className="space-y-6">
                  <div className="grid grid-cols-1 gap-3">
                    <TagBadge label="1 o 2: Nombre Completo" tag="1" />
                    <TagBadge label="4d: Número Licencia" tag="4d" />
                    <TagBadge label="4b: Vencimiento" tag="4b" />
                    <TagBadge label="3: Fecha Nacimiento" tag="3" />
                    <TagBadge label="8: Dirección" tag="8" />
                  </div>

                  <div className="pt-4 border-t border-slate-100">
                    <TagBadge label="Foto del Frente" tag="foto_frente" isImage />
                  </div>

                  <div className="p-3 bg-amber-50 border border-amber-100 rounded-xl">
                    <p className="text-[10px] text-amber-700 leading-tight">
