  const parts: any[] = [
    { inlineData: { data: frontBase64, mimeType: front.type } },
    { inlineData: { data: backBase64, mimeType: back.type } }
  ];

  let referenceInstruction = "";
  if (reference) {
    const refBase64 = await fileToBase64(reference);
    parts.push({ 
      inlineData: { 
        data: refBase64, 
        mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document" 
      } 
    });
    referenceInstruction = `
      EXTREMELY IMPORTANT: I have provided a REFERENCE Word document. 
      This document shows how a previous license was mapped. 
      Use it to understand which specific data points from the license images 
      should correspond to each JSON field.
    `;
  }

  const prompt = `
    Analyze these two images of a driver's license (Front and Back).
    ${referenceInstruction}

    Standard numerical codes often found on licenses:
    1: Surname/Last Name
    2: First Name(s)
    3: Date of Birth
    4a: Issue Date
    4b: Expiry Date
    4d: License/ID Number
    8: Address
    9: Category/Class

    Instructions:
    1. Identify fields using these numbers first.
    2. Use the provided reference document structure if available.
    3. Translate all extracted values to English.
    4. If a field is missing, use "N/A".
    5. Return valid JSON.
  `;

  parts.push({ text: prompt });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          fullName: { type: Type.STRING, description: "Combination of fields 1 and 2" },
          licenseNumber: { type: Type.STRING, description: "Field 4d or 5" },
          dateOfBirth: { type: Type.STRING, description: "Field 3" },
          issueDate: { type: Type.STRING, description: "Field 4a" },
          expiryDate: { type: Type.STRING, description: "Field 4b" },
          address: { type: Type.STRING, description: "Field 8" },
          nationality: { type: Type.STRING },
          gender: { type: Type.STRING },
          class: { type: Type.STRING, description: "Field 9" },
        },
        required: ["fullName", "licenseNumber"]
      }
    }
  });

  const jsonStr = response.text.trim();
  return JSON.parse(jsonStr) as ExtractedData;
};

import React, { useState } from 'react';
