import { GoogleGenAI, Type } from "@google/genai";
import PizZip from "pizzip";
import { ExtractedData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = error => reject(error);
  });
};

const extractTextFromDocx = async (file: File): Promise<string> => {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const zip = new PizZip(arrayBuffer);
    const docXml = zip.file("word/document.xml")?.asText();
    if (!docXml) return "";
    return docXml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  } catch (e) {
    console.error("Error leyendo Word de referencia:", e);
    return "";
  }
};

export const extractDataFromLicense = async (
  front: File,
  back: File,
  reference?: File | null
): Promise<ExtractedData> => {
  const frontBase64 = await fileToBase64(front);
  const backBase64 = await fileToBase64(back);

  const parts: any[] = [
    { inlineData: { data: frontBase64, mimeType: front.type } },
    { inlineData: { data: backBase64, mimeType: back.type } }
  ];

  let referenceInstruction = "";
  if (reference) {
    const referenceText = await extractTextFromDocx(reference);
    if (referenceText) {
      referenceInstruction = `
        REFERENCE CONTEXT (From previous filled document):
        "${referenceText}"
      `;
    }
  }

  const prompt = `
    Analyze these two images of a driver's license (Front and Back).
    ${referenceInstruction}

    SPECIAL INSTRUCTIONS:
    1. Translate all values to ENGLISH.
    2. Split the names: Field 1 is "surname", Field 2 is "firstNames".
    3. Field 4a is "issueDate".
    4. Field 4c is "authority". Format: "[Authority], France".
    5. TABLE ANALYSIS (BACK SIDE):
       - Look at the table columns 9 (Category) and 10 (Date of first issue).
       - Group categories that share the SAME date.
       - Format: "A, A1: 12 December 2025".
       - If ALL categories have the same date, return ONLY the date string.
       - Store this in "categoriesDates".
    6. Field 9 overall summary is "class".
    7. Alphanumeric series in top-left corner of BACK are "codes".

    Return valid JSON.
  `;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            surname: { type: Type.STRING },
            firstNames: { type: Type.STRING },
            fullName: { type: Type.STRING },
            licenseNumber: { type: Type.STRING },
            dateOfBirth: { type: Type.STRING },
            issueDate: { type: Type.STRING },
            expiryDate: { type: Type.STRING },
            address: { type: Type.STRING },
            nationality: { type: Type.STRING },
            gender: { type: Type.STRING },
            class: { type: Type.STRING },
            codes: { type: Type.STRING },
            authority: { type: Type.STRING },
            categoriesDates: { type: Type.STRING, description: "Grouped categories and their first issue dates from column 10" },
          },
          required: []
        }
      }
    });

    const jsonStr = response.text.trim();
    return JSON.parse(jsonStr) as ExtractedData;
  } catch (error: any) {
    console.error("Gemini Error:", error);
    throw new Error(error.message || "La IA no pudo procesar las imágenes.");
  }
};

import PizZip from "pizzip";
import Docxtemplater from "docxtemplater";
// @ts-ignore
import ImageModule from "docxtemplater-image-module-free";
import { ExtractedData } from "../types";

export const optimizeImage = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const maxWidth = 1000;
        const scale = img.width > maxWidth ? maxWidth / img.width : 1;
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        }
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
      img.onerror = () => reject(new Error("Error al procesar la imagen."));
      img.src = e.target?.result as string;
    };
    reader.onerror = () => reject(new Error("Error al leer el archivo."));
    reader.readAsDataURL(file);
  });
};

export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  frontImgBase64: string,
  backImgBase64: string
): Promise<Blob> => {
  try {
    const content = await template.arrayBuffer();
    const zip = new PizZip(content);

    const imageOptions = {
      centered: false,
      getImage: (tagValue: string) => {
        try {
          const base64 = tagValue.split(',')[1] || tagValue;
          const binaryString = window.atob(base64);
          const len = binaryString.length;
          const bytes = new Uint8Array(len);
          for (let i = 0; i < len; i++) {
            bytes[i] = binaryString.charCodeAt(i);
          }
          return bytes.buffer;
        } catch (e) {
          console.error("Image loading error:", e);
          return new ArrayBuffer(0);
        }
      },
      getSize: () => [240, 150],
    };

    const ImageModuleClass = typeof ImageModule === 'function' ? ImageModule : ImageModule.default;
    const imageModule = new ImageModuleClass(imageOptions);

    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      modules: [imageModule],
      delimiters: { start: '{{', end: '}}' },
      nullGetter() { return ""; }
    });

    const val = (v: any) => (v === undefined || v === null || v === "N/A" || v === "null" ? "" : v);

    const fullData: Record<string, any> = {
      surname: val(data.surname),
      firstNames: val(data.firstNames),
      fullName: val(data.fullName || `${data.surname} ${data.firstNames}`),
      licenseNumber: val(data.licenseNumber),
      dateOfBirth: val(data.dateOfBirth),
      issueDate: val(data.issueDate),
      expiryDate: val(data.expiryDate),
      address: val(data.address),
      class: val(data.class),
      codes: val(data.codes),
      authority: val(data.authority),

      // Nuevo: Fechas de categorías (Columna 10)
      categoriesDates: val(data.categoriesDates),
      fechasCategorias: val(data.categoriesDates),
      columna10: val(data.categoriesDates),

      nationality: val(data.nationality),
      gender: val(data.gender),
      foto_frente: frontImgBase64,
      foto_reverso: backImgBase64,
      license_front: frontImgBase64,
      license_back: backImgBase64,
      today: new Date().toLocaleDateString(),
    };

    doc.render(fullData);

    const out = doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });

    return out;
  } catch (error: any) {
    console.error("Docxtemplater Error:", error);
    throw new Error(error.message || "Error al procesar el archivo Word.");
  }
};

