const extractTextFromDocx = async (file: File): Promise<string> => {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const zip = new PizZip(arrayBuffer);
    const docXml = zip.file("word/document.xml")?.asText();
    if (!docXml) return "";
    return docXml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  } catch (e) {
    console.error("Error leyendo Word de referencia:", e);
    return "";
  }
};

export const extractDataFromLicense = async (
  front: File,
  back: File,
  reference?: File | null
): Promise<ExtractedData> => {
  const frontBase64 = await fileToBase64(front);
  const backBase64 = await fileToBase64(back);

  const parts: any[] = [
    { inlineData: { data: frontBase64, mimeType: front.type } },
    { inlineData: { data: backBase64, mimeType: back.type } }
  ];

  let referenceInstruction = "";
  if (reference) {
    const referenceText = await extractTextFromDocx(reference);
    if (referenceText) {
      referenceInstruction = `
        REFERENCE CONTEXT (From previous filled document):
        "${referenceText}"
      `;
    }
  }

  const prompt = `
    Analyze these two images of a driver's license (Front and Back).
    ${referenceInstruction}

    CRITICAL DATE FORMATTING RULE:
    All dates (date of birth, issue date, expiry date, and table dates) MUST be formatted as: "DD Month YYYY" in ENGLISH.
    Example: "01 January 2025". Never use numbers for months.

    SPECIAL INSTRUCTIONS:
    1. Translate all values to ENGLISH.
    2. Split the names: Field 1 is "surname", Field 2 is "firstNames".
    3. FIELD 3 ANALYSIS: 
       - Extract the date part into "dateOfBirth" (Format: DD Month YYYY).
       - Extract the city/place part into "placeOfBirth".
    4. Field 4a is "issueDate" (Format: DD Month YYYY).
    5. Field 4b is "expiryDate" (Format: DD Month YYYY).
    6. Field 4c is "authority". Format: "[Authority], France".
    7. FIELD 9 ANALYSIS (Categories):
       - Extract the authorized categories listed in field 9.
       - Format them as a clean, comma-separated list (e.g., "A, B, BE, D1").
       - Store this in "class".
    8. TABLE ANALYSIS (BACK SIDE):
       - Look at the table columns 9 (Category) and 10 (Date of first issue).
       - Group categories that share the SAME date.
       - Format: "A, A1: 12 December 2025".
       - If ALL categories have the same date, return ONLY the date string (Format: DD Month YYYY).
       - Store this in "categoriesDates".
    9. Alphanumeric series in top-left corner of BACK are "codes".

    Return valid JSON.
  `;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            surname: { type: Type.STRING },
            firstNames: { type: Type.STRING },
            fullName: { type: Type.STRING },
            licenseNumber: { type: Type.STRING },
            dateOfBirth: { type: Type.STRING },
            placeOfBirth: { type: Type.STRING },
            issueDate: { type: Type.STRING },
            expiryDate: { type: Type.STRING },
            address: { type: Type.STRING },
            nationality: { type: Type.STRING },
            gender: { type: Type.STRING },
            class: { type: Type.STRING, description: "List of categories from field 9, e.g. A, B, C" },
            codes: { type: Type.STRING },
            authority: { type: Type.STRING },
            categoriesDates: { type: Type.STRING },
          },
          required: []
        }
      }
    });

    const jsonStr = response.text.trim();
    return JSON.parse(jsonStr) as ExtractedData;
  } catch (error: any) {
    console.error("Gemini Error:", error);
    throw new Error(error.message || "La IA no pudo procesar las imágenes.");
  }
};

import PizZip from "pizzip";
import Docxtemplater from "docxtemplater";
// @ts-ignore
import ImageModule from "docxtemplater-image-module-free";
import { ExtractedData } from "../types";

export const optimizeImage = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const maxWidth = 1000;
        const scale = img.width > maxWidth ? maxWidth / img.width : 1;
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        }
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
      img.onerror = () => reject(new Error("Error al procesar la imagen."));
      img.src = e.target?.result as string;
    };
    reader.onerror = () => reject(new Error("Error al leer el archivo."));
    reader.readAsDataURL(file);
  });
};

export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  frontImgBase64: string,
  backImgBase64: string
): Promise<Blob> => {
  try {
    const content = await template.arrayBuffer();
    const zip = new PizZip(content);

    const imageOptions = {
      centered: false,
      getImage: (tagValue: string) => {
        try {
          const base64 = tagValue.split(',')[1] || tagValue;
          const binaryString = window.atob(base64);
          const len = binaryString.length;
          const bytes = new Uint8Array(len);
          for (let i = 0; i < len; i++) {
            bytes[i] = binaryString.charCodeAt(i);
          }
          return bytes.buffer;
        } catch (e) {
          console.error("Image loading error:", e);
          return new ArrayBuffer(0);
        }
      },
      getSize: () => [240, 150],
    };

    const ImageModuleClass = typeof ImageModule === 'function' ? ImageModule : ImageModule.default;
    const imageModule = new ImageModuleClass(imageOptions);

    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      modules: [imageModule],
      delimiters: { start: '{{', end: '}}' },
      nullGetter() { return ""; }
    });

    const val = (v: any) => (v === undefined || v === null || v === "N/A" || v === "null" ? "" : v);

    const fullData: Record<string, any> = {
      surname: val(data.surname),
      firstNames: val(data.firstNames),
      fullName: val(data.fullName || `${data.surname} ${data.firstNames}`),
      licenseNumber: val(data.licenseNumber),
      dateOfBirth: val(data.dateOfBirth),
      placeOfBirth: val(data.placeOfBirth),
      lugarNacimiento: val(data.placeOfBirth),
      cityOfBirth: val(data.placeOfBirth),
      issueDate: val(data.issueDate),
      expiryDate: val(data.expiryDate),
      address: val(data.address),

      // Campo 9: Clases/Categorías
      class: val(data.class),
      clases: val(data.class),
      categorias: val(data.class),
      categories: val(data.class),

      codes: val(data.codes),
      authority: val(data.authority),
      categoriesDates: val(data.categoriesDates),
      fechasCategorias: val(data.categoriesDates),
      columna10: val(data.categoriesDates),
      nationality: val(data.nationality),
      gender: val(data.gender),
      foto_frente: frontImgBase64,
      foto_reverso: backImgBase64,
      license_front: frontImgBase64,
      license_back: backImgBase64,
      today: new Date().toLocaleDateString(),
    };

    doc.render(fullData);

    const out = doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });

    return out;
  } catch (error: any) {
    console.error("Docxtemplater Error:", error);
    throw new Error(error.message || "Error al procesar el archivo Word.");
  }
};

import React, { useState } from 'react';
import { 
  FileText, Cpu, Download, Loader2, Info, 
  CheckCircle2, Copy, XCircle, Sparkles, AlertTriangle
} from 'lucide-react';
import FileUploader from './components/FileUploader';
import DataPreview from './components/DataPreview';
import { extractDataFromLicense } from './services/geminiService';
import { generateFilledDoc, optimizeImage } from './services/docService';
import { AppState, ProcessStatus } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    templateFile: null,
    referenceFile: null,
    frontImage: null,
    backImage: null,
    status: ProcessStatus.IDLE,
    extractedData: null,
    error: null,
  });

  const [previews, setPreviews] = useState<{ front: string | null; back: string | null }>({
    front: null,
    back: null,
  });

  const handleProcess = async () => {
    if (!state.templateFile || !state.frontImage || !state.backImage) {
      setState(prev => ({ ...prev, error: "Faltan archivos obligatorios (Plantilla y Fotos)." }));
      return;
    }

    setState(prev => ({ ...prev, status: ProcessStatus.PROCESSING, error: null }));

    try {
      const frontOpt = await optimizeImage(state.frontImage);
      const backOpt = await optimizeImage(state.backImage);
      setPreviews({ front: frontOpt, back: backOpt });

      const data = await extractDataFromLicense(
        state.frontImage, 
        state.backImage, 
        state.referenceFile
      );

      setState(prev => ({ ...prev, status: ProcessStatus.REVIEW, extractedData: data }));
    } catch (err: any) {
      console.error("Process Error:", err);
      setState(prev => ({ 
        ...prev, 
        status: ProcessStatus.ERROR, 
        error: err.message || "Error desconocido al procesar archivos." 
      }));
    }
  };

  const handleFinalize = async () => {
    if (!state.templateFile || !state.extractedData || !previews.front || !previews.back) return;
    setState(prev => ({ ...prev, error: null }));
    try {
      const blob = await generateFilledDoc(state.templateFile, state.extractedData, previews.front, previews.back);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      const fileName = (state.extractedData.surname || "Documento").replace(/\s+/g, '_');
      a.download = `Llenado_${fileName}.docx`;
      document.body.appendChild(a);
      a.click();
      setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 100);
      setState(prev => ({ ...prev, status: ProcessStatus.COMPLETED }));
    } catch (err: any) {
      setState(prev => ({ ...prev, error: `Error al generar el Word: ${err.message}` }));
    }
  };

  const copyToClipboard = (text: string) => navigator.clipboard.writeText(text);

  const TagBadge = ({ tag, label, isImage = false }: { tag: string; label: string; isImage?: boolean }) => (
    <div className="flex flex-col gap-1">
      <span className="text-[9px] font-bold text-slate-400 uppercase">{label}</span>
      <button 
        onClick={() => copyToClipboard(isImage ? `{%${tag}}` : `{{${tag}}}`)}
        className={`flex items-center justify-between gap-2 px-3 py-1.5 rounded-lg font-mono text-[11px] border transition-all active:scale-95
          ${isImage ? 'bg-indigo-50 border-indigo-200 text-indigo-700 hover:bg-indigo-100' : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'}`}
      >
        {isImage ? `{%${tag}}` : `{{${tag}}}`}
        <Copy size={12} />
      </button>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#f8fafc] py-12 px-4 flex flex-col items-center">
      <header className="max-w-6xl w-full text-center mb-12">
        <div className="bg-indigo-600 w-16 h-16 rounded-2xl shadow-xl flex items-center justify-center mx-auto mb-4">
          <FileText className="text-white" size={32} />
        </div>
        <h1 className="text-3xl font-black text-slate-900">DocuFill AI</h1>
        <p className="text-slate-500 mt-2 font-medium">Automatización Profesional de Licencias</p>
      </header>

      <main className="max-w-6xl w-full">
        {(state.status === ProcessStatus.IDLE || state.status === ProcessStatus.ERROR) && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <aside className="lg:col-span-3 space-y-6">
              <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2 text-sm">
                  <Info size={16} className="text-indigo-600" /> Atajos de Plantilla
                </h3>
                <div className="space-y-4">
                  <div className="grid grid-cols-1 gap-2.5">
                    <TagBadge label="1: Apellidos" tag="surname" />
                    <TagBadge label="2: Nombres" tag="firstNames" />
                    <TagBadge label="3: Lugar Nac" tag="placeOfBirth" />
                    <TagBadge label="3: Fecha Nac" tag="dateOfBirth" />
                    <TagBadge label="4a: Expedición" tag="issueDate" />
                    <TagBadge label="4c: Autoridad" tag="authority" />
                    <TagBadge label="9: Clases" tag="clases" />
                    <TagBadge label="10: Fechas Cat" tag="categoriesDates" />
                    <TagBadge label="Reverso: Códigos" tag="codes" />
                  </div>
                  <div className="pt-3 border-t border-slate-100">
                    <TagBadge label="Foto Frente" tag="foto_frente" isImage />
                  </div>
                </div>
              </div>
            </aside>

            <section className="lg:col-span-9 space-y-8">
              {state.error && (
                <div className="bg-red-50 text-red-700 p-5 rounded-2xl border border-red-200 flex items-start gap-4 animate-in fade-in zoom-in">
                  <AlertTriangle size={24} className="shrink-0 text-red-500" />
                  <div className="flex-1">
                    <p className="text-sm font-black uppercase tracking-tight">Error de Procesamiento</p>
                    <p className="text-xs mt-1 font-medium leading-relaxed">{state.error}</p>
                  </div>
                  <button onClick={() => setState(p => ({...p, error: null}))} className="text-red-400 hover:text-red-600">
                    <XCircle size={20} />
                  </button>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-3xl border border-slate-200 flex flex-col shadow-sm">
                  <span className="bg-slate-100 text-slate-600 text-[10px] font-black px-2 py-1 rounded w-fit mb-3 uppercase">Plantilla</span>
                  <FileUploader label="Word Base (.docx)" accept=".docx" selectedFile={state.templateFile} onFileSelect={(f) => setState(p => ({...p, templateFile: f}))} />
                </div>

                <div className="bg-indigo-50/40 p-6 rounded-3xl border border-indigo-100 flex flex-col shadow-sm">
                  <span className="bg-indigo-100 text-indigo-600 text-[10px] font-black px-2 py-1 rounded w-fit mb-3 uppercase">IA Inteligente</span>
                  <FileUploader label="Doc Referencia (Opc)" accept=".docx" selectedFile={state.referenceFile} onFileSelect={(f) => setState(p => ({...p, referenceFile: f}))} />
                </div>

                <div className="bg-white p-6 rounded-3xl border border-slate-200 flex flex-col shadow-sm">
                  <span className="bg-slate-100 text-slate-600 text-[10px] font-black px-2 py-1 rounded w-fit mb-3 uppercase">Fotos</span>
                  <div className="space-y-3">
                    <FileUploader label="Frente" accept="image/*" icon="image" selectedFile={state.frontImage} onFileSelect={(f) => setState(p => ({...p, frontImage: f}))} />
                    <FileUploader label="Reverso" accept="image/*" icon="image" selectedFile={state.backImage} onFileSelect={(f) => setState(p => ({...p, backImage: f}))} />
                  </div>
                </div>
              </div>

              <button 
                onClick={handleProcess}
                disabled={!state.templateFile || !state.frontImage || !state.backImage || state.status === ProcessStatus.PROCESSING}
                className="w-full bg-indigo-600 text-white py-6 rounded-2xl font-black text-lg hover:bg-indigo-700 disabled:opacity-40 transition-all shadow-xl hover:shadow-indigo-200 flex items-center justify-center gap-3 active:scale-[0.98]"
              >
                <Cpu size={24} /> ANALIZAR Y TRADUCIR
              </button>
            </section>
          </div>
        )}

        {state.status === ProcessStatus.PROCESSING && (
          <div className="bg-white p-20 rounded-[3rem] text-center space-y-4 max-w-xl mx-auto shadow-xl border border-slate-100">
            <Loader2 className="mx-auto animate-spin text-indigo-600 mb-4" size={60} />
            <h2 className="text-2xl font-black text-slate-800">Procesando con IA...</h2>
            <p className="text-slate-500 text-sm">Extrayendo categorías permitidas (Campo 9) y formateando datos.</p>
          </div>
        )}

        {state.status === ProcessStatus.REVIEW && state.extractedData && (
          <div className="max-w-4xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-4">
            <div className="flex items-center justify-between bg-white px-6 py-4 rounded-2xl border border-slate-100 shadow-sm">
