import PizZip from "pizzip";
import Docxtemplater from "docxtemplater";
// @ts-ignore
import ImageModule from "docxtemplater-image-module-free";
import { ExtractedData } from "../types";

/**
 * Optimiza la imagen para que no sea demasiado pesada en el Word.
 */
export const optimizeImage = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const maxWidth = 800; // Reducido para mayor compatibilidad
        const scale = img.width > maxWidth ? maxWidth / img.width : 1;
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        }
        resolve(canvas.toDataURL('image/jpeg', 0.8));
      };
      img.onerror = () => reject(new Error("No se pudo cargar la imagen para optimizarla."));
      img.src = e.target?.result as string;
    };
    reader.onerror = () => reject(new Error("Error al leer el archivo de imagen."));
    reader.readAsDataURL(file);
  });
};

/**
 * Genera el archivo Word (.docx) llenando los campos de la plantilla.
 */
export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  frontImgBase64: string,
  backImgBase64: string
): Promise<Blob> => {
  try {
    const arrayBuffer = await template.arrayBuffer();
    // Es vital pasar el contenido como Uint8Array para archivos binarios (.docx)
    const zip = new PizZip(new Uint8Array(arrayBuffer));

    const imageOptions = {
      centered: false,
      getImage: (tagValue: string) => {
        try {
          // Extraer solo la parte base64 si viene con el prefijo data:image/...
          const base64 = tagValue.includes(',') ? tagValue.split(',')[1] : tagValue;
          const binaryString = window.atob(base64);
          const len = binaryString.length;
          const bytes = new Uint8Array(len);
          for (let i = 0; i < len; i++) {
            bytes[i] = binaryString.charCodeAt(i);
          }
          return bytes.buffer;
        } catch (e) {
          console.error("Error al procesar imagen para la plantilla:", e);
          return new ArrayBuffer(0);
        }
      },
      getSize: () => [240, 150], // Tamaño por defecto en puntos
    };

    // Ajuste de compatibilidad para el módulo de imágenes según cómo lo entregue el CDN
    const ImageModuleClass = ImageModule.default || ImageModule;
    const imageModule = new ImageModuleClass(imageOptions);

    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      modules: [imageModule],
      delimiters: { start: '{{', end: '}}' },
      nullGetter() { return ""; } // Evita que aparezca "undefined" en el Word
    });

    const val = (v: any) => (v === undefined || v === null || v === "N/A" || v === "null" ? "" : String(v));

    // Mapeo de datos para la plantilla
    const fullData: Record<string, any> = {
      surname: val(data.surname),
      firstNames: val(data.firstNames),
      fullName: val(data.fullName || `${data.surname} ${data.firstNames}`),
      licenseNumber: val(data.licenseNumber),
      dateOfBirth: val(data.dateOfBirth),
      placeOfBirth: val(data.placeOfBirth),
      lugarNacimiento: val(data.placeOfBirth),
      cityOfBirth: val(data.placeOfBirth),
      issueDate: val(data.issueDate),
      expiryDate: val(data.expiryDate),
      address: val(data.address),

      class: val(data.class),
      clases: val(data.class),
      categorias: val(data.class),
      categories: val(data.class),

      codes: val(data.codes),
      authority: val(data.authority),
      categoriesDates: val(data.categoriesDates),
      fechasCategorias: val(data.categoriesDates),
      columna10: val(data.categoriesDates),
      nationality: val(data.nationality),
      gender: val(data.gender),

      // Etiquetas para imágenes (se usan con {%tag})
      foto_frente: frontImgBase64,
      foto_reverso: backImgBase64,
      license_front: frontImgBase64,
      license_back: backImgBase64,

      today: new Date().toLocaleDateString(),
    };

    // Intentar renderizar el documento
    doc.render(fullData);

    // Generar el Blob de salida
    const out = doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });

    return out;
  } catch (error: any) {
    console.error("Detalle del error en generateFilledDoc:", error);

    // Si el error es de Docxtemplater, suele traer información de qué etiqueta falló
    if (error.properties && error.properties.errors instanceof Array) {
      const errorMessages = error.properties.errors
        .map((e: any) => e.properties.explanation)
        .join("\n");
      throw new Error(`Error en la plantilla Word: ${errorMessages}`);
    }

    throw new Error(error.message || "Error desconocido al generar el archivo Word.");
  }
};

