import React, { useState, useEffect } from 'react';
import { 
  FileText, Cpu, Download, Loader2, 
  CheckCircle2, XCircle, AlertTriangle, Clipboard
} from 'lucide-react';
import FileUploader from './components/FileUploader';
import DataPreview from './components/DataPreview';
import { extractDataFromLicense } from './services/geminiService';
import { generateFilledDoc, optimizeImage } from './services/docService';
import { AppState, ProcessStatus } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    templateFile: null,
    referenceFile: null,
    frontImage: null,
    backImage: null,
    status: ProcessStatus.IDLE,
    extractedData: null,
    error: null,
  });

  useEffect(() => {
    const handlePaste = (event: ClipboardEvent) => {
      const items = event.clipboardData?.items;
      if (!items) return;

      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            const file = new File([blob], `pasted-image-${Date.now()}.png`, { type: blob.type });
            setState(prev => {
              if (!prev.frontImage) return { ...prev, frontImage: file, error: null };
              else if (!prev.backImage) return { ...prev, backImage: file, error: null };
              return prev;
            });
          }
          break;
        }
      }
    };
    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, []);

  const handleProcess = async () => {
    if (!state.templateFile || !state.frontImage || !state.backImage) {
      setState(prev => ({ ...prev, error: "Faltan archivos obligatorios." }));
      return;
    }
    setState(prev => ({ ...prev, status: ProcessStatus.PROCESSING, error: null }));
    try {
      const data = await extractDataFromLicense(state.frontImage, state.backImage, state.referenceFile);
      setState(prev => ({ ...prev, status: ProcessStatus.REVIEW, extractedData: data }));
    } catch (err: any) {
      setState(prev => ({ ...prev, status: ProcessStatus.ERROR, error: err.message }));
    }
  };

  const handleFinalize = async () => {
    if (!state.templateFile || !state.extractedData || !state.frontImage || !state.backImage) return;
    setState(prev => ({ ...prev, status: ProcessStatus.PROCESSING }));
    try {
      const frontBase64 = await optimizeImage(state.frontImage);
      const backBase64 = await optimizeImage(state.backImage);
      const blob = await generateFilledDoc(state.templateFile, state.extractedData, frontBase64, backBase64);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Llenado_${state.extractedData.surname || 'Doc'}.docx`;
      a.click();
      setState(prev => ({ ...prev, status: ProcessStatus.COMPLETED }));
    } catch (err: any) {
      setState(prev => ({ ...prev, status: ProcessStatus.REVIEW, error: err.message }));
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] py-12 px-4 flex flex-col items-center font-sans text-slate-900">
      <header className="max-w-6xl w-full text-center mb-12">
        <div className="bg-indigo-600 w-16 h-16 rounded-2xl shadow-xl flex items-center justify-center mx-auto mb-4">
          <FileText className="text-white" size={32} />
        </div>
        <h1 className="text-3xl font-black text-slate-900 tracking-tight">DocuFill AI</h1>
        <p className="text-slate-500 mt-2 font-medium">Automatización Inteligente</p>
      </header>

      <main className="max-w-6xl w-full">
        {state.error && (
          <div className="max-w-4xl mx-auto mb-8 bg-red-50 text-red-700 p-5 rounded-2xl border border-red-200 flex items-start gap-4 shadow-sm">
            <AlertTriangle size={24} className="shrink-0 text-red-500" />
            <div className="flex-1 text-xs font-medium">{state.error}</div>
            <button onClick={() => setState(p => ({...p, error: null}))}><XCircle size={20} /></button>
          </div>
        )}

        {(state.status === ProcessStatus.IDLE || state.status === ProcessStatus.ERROR) && (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            <aside className="lg:col-span-1">
              <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm sticky top-8">
                <h3 className="font-bold text-slate-800 mb-4 text-xs uppercase tracking-widest flex items-center gap-2">
                  <Clipboard size={14} className="text-indigo-500" /> Etiquetas Word
                </h3>
                <div className="space-y-2">
                  <div className="p-2 bg-slate-50 rounded-lg text-[10px] font-mono text-slate-500 border border-slate-100">{'{{surname}}'}</div>
                  <div className="p-2 bg-slate-50 rounded-lg text-[10px] font-mono text-slate-500 border border-slate-100">{'{{class}}'}</div>
                  <div className="p-2 bg-slate-50 rounded-lg text-[10px] font-mono text-slate-500 border border-slate-100">{'{{codes}}'}</div>
                  <div className="p-2 bg-indigo-50 rounded-lg text-[10px] font-mono text-indigo-600 border border-indigo-100 font-bold">{'{{code106From}}'}</div>
                  <div className="p-2 bg-indigo-50 rounded-lg text-[10px] font-mono text-indigo-600 border border-indigo-100 font-bold">{'{{code106To}}'}</div>
                  <div className="p-2 bg-indigo-50 rounded-lg text-[10px] font-mono text-indigo-500 border border-indigo-100">{'{%foto_frente}'}</div>
                </div>
              </div>
            </aside>

            <section className="lg:col-span-3 space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <FileUploader label="Plantilla (.docx)" accept=".docx" selectedFile={state.templateFile} onFileSelect={(f) => setState(p => ({...p, templateFile: f}))} />
                <FileUploader label="Referencia (Opc)" accept=".docx" selectedFile={state.referenceFile} onFileSelect={(f) => setState(p => ({...p, referenceFile: f}))} />
                <div className="space-y-4">
                  <FileUploader label="Foto Frente" accept="image/*" icon="image" selectedFile={state.frontImage} onFileSelect={(f) => setState(p => ({...p, frontImage: f}))} />
                  <FileUploader label="Foto Reverso" accept="image/*" icon="image" selectedFile={state.backImage} onFileSelect={(f) => setState(p => ({...p, backImage: f}))} />
                </div>
              </div>
              <button 
                onClick={handleProcess}
                disabled={!state.templateFile || !state.frontImage || !state.backImage || state.status === ProcessStatus.PROCESSING}
                className="w-full bg-indigo-600 text-white py-6 rounded-2xl font-black text-lg hover:bg-indigo-700 disabled:opacity-40 shadow-xl transition-all flex items-center justify-center gap-3"
              >
                <Cpu size={24} /> ANALIZAR LICENCIA
              </button>
            </section>
          </div>
        )}

        {state.status === ProcessStatus.PROCESSING && (
          <div className="bg-white p-20 rounded-[3rem] text-center space-y-4 max-w-xl mx-auto shadow-xl border border-slate-100">
            <Loader2 className="mx-auto animate-spin text-indigo-600" size={60} />
            <h2 className="text-2xl font-black text-slate-800">Analizando...</h2>
            <p className="text-slate-500 text-sm">Buscando el código 106 y sus fechas de validez.</p>
          </div>
        )}

        {state.status === ProcessStatus.REVIEW && state.extractedData && (
          <div className="max-w-4xl mx-auto space-y-6">
            <DataPreview data={state.extractedData} onChange={(d) => setState(p => ({...p, extractedData: d}))} />
            <button onClick={handleFinalize} className="w-full bg-emerald-600 text-white py-6 rounded-2xl font-black text-xl hover:bg-emerald-700 shadow-xl flex items-center justify-center gap-4 transition-all">
              <Download size={28} /> GENERAR DOCUMENTO WORD
            </button>
          </div>
        )}

        {state.status === ProcessStatus.COMPLETED && (
          <div className="bg-white p-16 rounded-[3rem] text-center space-y-6 max-w-xl mx-auto shadow-2xl border border-slate-100">
            <CheckCircle2 size={64} className="mx-auto text-emerald-500" />
            <h2 className="text-3xl font-black text-slate-900">Documento Listo</h2>
            <button onClick={() => window.location.reload()} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-lg">NUEVA LICENCIA</button>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import PizZip from "pizzip";
import { ExtractedData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = error => reject(error);
  });
};

const extractTextFromDocx = async (file: File): Promise<string> => {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const zip = new PizZip(arrayBuffer);
    const docXml = zip.file("word/document.xml")?.asText();
    if (!docXml) return "";
    return docXml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  } catch (e) {
    console.error("Error leyendo Word de referencia:", e);
    return "";
  }
};

export const extractDataFromLicense = async (
  front: File,
  back: File,
  reference?: File | null
): Promise<ExtractedData> => {
  const frontBase64 = await fileToBase64(front);
  const backBase64 = await fileToBase64(back);

  const parts: any[] = [
    { inlineData: { data: frontBase64, mimeType: front.type } },
    { inlineData: { data: backBase64, mimeType: back.type } }
  ];

  let referenceInstruction = "";
  if (reference) {
    const referenceText = await extractTextFromDocx(reference);
    if (referenceText) {
      referenceInstruction = `REFERENCE CONTEXT FROM PREVIOUS DOCUMENT: "${referenceText}"`;
    }
  }

  const prompt = `
    Analyze these two images (Front and Back of a Japanese driver's license).
    ${referenceInstruction}

    CRITICAL RULE: TRANSLATE EVERYTHING TO ENGLISH. 
    NO JAPANESE CHARACTERS (Kanji, Hiragana, Katakana) should remain in the output.

    EXTRACT DATA RULES:
    1. "surname": Family name. If written in Japanese, provide the Romaji/English translation.
    2. "firstNames": Given names. If written in Japanese, provide the Romaji/English translation.
    3. "licenseNumber": The main identification number (usually 12 digits).
    4. "dateOfBirth": Date from Point 3. Translate months to English (e.g., January).
    5. "placeOfBirth": Location from Point 3. Translate city/prefecture to English (e.g., "Tokyo" instead of "東京都").
    6. "issueDate": Point 4a. Format: DD Month YYYY.
    7. "expiryDate": Point 4b. Format: DD Month YYYY.
    8. "authority": Point 4c. Translate to English (e.g., "Tokyo Metropolitan Public Safety Commission").
    9. "class": Extract ALL categories from Point 9 on the FRONT. TRANSLATE them (e.g., "Ordinary" for 普通, "Large" for 大型, etc.).
    10. "categoriesDates": Analyze the BACK table, Column 10. Group identical dates. All months in English.
    11. "codes": Look at the TOP LEFT corner (horizontal/vertical numbers) and Column 12. List them clearly.
    12. SPECIAL CODE 106: If found, extract "code106From" and "code106To" (dates in DD Month YYYY).
    13. "address": Translate the full address to English/Romaji.

    Strictly follow the JSON schema and ensure 100% English translation.
  `;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            surname: { type: Type.STRING },
            firstNames: { type: Type.STRING },
            fullName: { type: Type.STRING },
            licenseNumber: { type: Type.STRING },
            dateOfBirth: { type: Type.STRING },
            placeOfBirth: { type: Type.STRING },
            issueDate: { type: Type.STRING },
            expiryDate: { type: Type.STRING },
            address: { type: Type.STRING },
            class: { type: Type.STRING },
            codes: { type: Type.STRING },
            authority: { type: Type.STRING },
            categoriesDates: { type: Type.STRING },
            code106From: { type: Type.STRING },
            code106To: { type: Type.STRING },
          }
        }
      }
    });

    const result = JSON.parse(response.text.trim());
    if (!result.fullName) {
      result.fullName = `${result.surname || ''} ${result.firstNames || ''}`.trim();
    }
    return result as ExtractedData;
  } catch (error: any) {
    console.error("Gemini Error:", error);
    throw new Error(error.message || "La IA no pudo procesar las imágenes.");
  }
};

