                  <div className="p-2 bg-slate-50 rounded-lg text-[10px] font-mono text-slate-500 border border-slate-100">{'{{class}}'}</div>
                  <div className="p-2 bg-slate-50 rounded-lg text-[10px] font-mono text-slate-500 border border-slate-100">{'{{codes}}'}</div>
                  <div className="p-2 bg-indigo-50 rounded-lg text-[10px] font-mono text-indigo-600 border border-indigo-100 font-bold">{'{{code106From}}'}</div>
                  <div className="p-2 bg-indigo-50 rounded-lg text-[10px] font-mono text-indigo-600 border border-indigo-100 font-bold">{'{{code106To}}'}</div>
                  <div className="p-2 bg-indigo-50 rounded-lg text-[10px] font-mono text-indigo-500 border border-indigo-100">{'{%license_front}'}</div>
