import { GoogleGenAI, Type } from "@google/genai";
import PizZip from "pizzip";
import { ExtractedData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = error => reject(error);
  });
};

const extractTextFromDocx = async (file: File): Promise<string> => {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const zip = new PizZip(arrayBuffer);
    const docXml = zip.file("word/document.xml")?.asText();
    if (!docXml) return "";
    return docXml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  } catch (e) {
    console.error("Error reading reference Word:", e);
    return "";
  }
};

export const extractDataFromLicense = async (
  front: File,
  back: File,
  reference?: File | null
): Promise<ExtractedData> => {
  const frontBase64 = await fileToBase64(front);
  const backBase64 = await fileToBase64(back);

  const parts: any[] = [
    { inlineData: { data: frontBase64, mimeType: front.type } },
    { inlineData: { data: backBase64, mimeType: back.type } }
  ];

  let referenceInstruction = "";
  if (reference) {
    const referenceText = await extractTextFromDocx(reference);
    if (referenceText) {
      referenceInstruction = `REFERENCE CONTEXT FROM PREVIOUS DOCUMENT: "${referenceText}"`;
    }
  }

  const prompt = `
    Analyze these two images (Front and Back of a Japanese driver's license).
    ${referenceInstruction}

    CRITICAL RULE: TRANSLATE EVERYTHING TO ENGLISH. 
    NO JAPANESE CHARACTERS (Kanji, Hiragana, Katakana) should remain in the output.

    EXTRACT DATA RULES:
    1. "surname": Family name. Provide the Romaji/English translation.
    2. "firstNames": Given names. Provide the Romaji/English translation.
    3. "licenseNumber": The main identification number (usually 12 digits).
    4. "dateOfBirth": Date from Point 3. Translate months to English (e.g., January).
    5. "placeOfBirth": Location from Point 3. Translate city/prefecture to English (e.g., "Tokyo" instead of "東京都").
    6. "issueDate": Point 4a. Format: DD Month YYYY.
    7. "expiryDate": Point 4b. Format: DD Month YYYY.
    8. "authority": Point 4c. Translate to English (e.g., "Mie Prefecture Public Safety Commission"). 
       IMPORTANT: ALWAYS suffix the authority with ", Japan" (e.g., "Mie Prefecture Public Safety Commission, Japan").
    9. "class": Extract ALL categories from Point 9 on the FRONT. Translate them (e.g., "Ordinary" for 普通, "Large" for 大型, etc.).
    10. "categoriesDates": Analyze the BACK table, Column 10. Group identical dates. All months in English.
    11. "codes": Look at the TOP LEFT corner (horizontal/vertical numbers) and Column 12. List them clearly.
    12. SPECIAL CODE 106: If found, extract "code106From" and "code106To" (dates in DD Month YYYY).
    13. "address": Translate the full address to English/Romaji.

    Strictly follow the JSON schema and ensure 100% English translation.
  `;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            surname: { type: Type.STRING },
            firstNames: { type: Type.STRING },
            fullName: { type: Type.STRING },
            licenseNumber: { type: Type.STRING },
            dateOfBirth: { type: Type.STRING },
            placeOfBirth: { type: Type.STRING },
            issueDate: { type: Type.STRING },
            expiryDate: { type: Type.STRING },
            address: { type: Type.STRING },
            class: { type: Type.STRING },
            codes: { type: Type.STRING },
            authority: { type: Type.STRING },
            categoriesDates: { type: Type.STRING },
            code106From: { type: Type.STRING },
            code106To: { type: Type.STRING },
          }
        }
      }
    });

    const result = JSON.parse(response.text.trim());
    if (!result.fullName) {
      result.fullName = `${result.surname || ''} ${result.firstNames || ''}`.trim();
    }
    return result as ExtractedData;
  } catch (error: any) {
    console.error("Gemini Error:", error);
    throw new Error(error.message || "The AI could not process the images.");
  }
};

