              onClick={handleProcess}
              disabled={!state.templateFile || !state.frontImage || !state.backImage || state.status === ProcessStatus.PROCESSING}
              className="w-full bg-indigo-600 text-white py-6 rounded-2xl font-black text-lg hover:bg-indigo-700 disabled:opacity-40 shadow-xl transition-all flex items-center justify-center gap-3"
            >
              <Cpu size={24} /> ANALYZE LICENSE
            </button>
          </div>
        )}

        {state.status === ProcessStatus.PROCESSING && (
          <div className="bg-white p-20 rounded-[3rem] text-center space-y-4 max-w-xl mx-auto shadow-xl border border-slate-100">
            <Loader2 className="mx-auto animate-spin text-indigo-600" size={60} />
            <h2 className="text-2xl font-black text-slate-800">Analyzing...</h2>
            <p className="text-slate-500 text-sm">Translating all data to English and looking for Code 106.</p>
          </div>
        )}

        {state.status === ProcessStatus.REVIEW && state.extractedData && (
          <div className="space-y-6">
            <DataPreview data={state.extractedData} onChange={(d) => setState(p => ({...p, extractedData: d}))} />
            <button onClick={handleFinalize} className="w-full bg-emerald-600 text-white py-6 rounded-2xl font-black text-xl hover:bg-emerald-700 shadow-xl flex items-center justify-center gap-4 transition-all">
              <Download size={28} /> GENERATE WORD DOCUMENT
            </button>
          </div>
        )}

        {state.status === ProcessStatus.COMPLETED && (
          <div className="bg-white p-16 rounded-[3rem] text-center space-y-6 max-w-xl mx-auto shadow-2xl border border-slate-100">
            <CheckCircle2 size={64} className="mx-auto text-emerald-500" />
            <h2 className="text-3xl font-black text-slate-900">Document Ready</h2>
            <button onClick={() => window.location.reload()} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-lg">NEW LICENSE</button>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;
